import re
def get_spans(html):
    i=html.find("<div id='bytes'>"); j=html.find("</div>\n    <div id='ascii'>")
    b=html[i+len("<div id='bytes'>"):j]
    tokens=re.findall(r"<[^>]+>|[^<]+", b)
    bytepos=0; stack=[]; res=[]
    for tok in tokens:
        if tok.startswith("<"):
            if tok.startswith("</"):
                name,start = stack.pop()
                res.append((start,bytepos,name))
            else:
                m=re.search(r"class='([^']+)'",tok)
                name=m.group(1) if m else tok
                stack.append((name,bytepos))
        else:
            toks=re.findall(r"&nbsp;.|[0-9a-fA-F]{2}", tok)
            bytepos+=len(toks)
    return res

def print_spans(html, filt=None):
    for s,e,n in get_spans(html):
        if filt is None or any(f in n for f in filt):
            print(s,e,n)
