import struct, subprocess, os, sys
def make_elf(phoff=0, shoff=0, phnum=0, shnum=0, total=1024, phdr_data=None, shdr_data=None, ehsize=64):
    data=bytearray(b'\x00'*total)
    ident=b'\x7fELF'+bytes([2,1,1,0,0])+b'\x00'*7
    ehdr=ident+struct.pack('<HHIQQQIHHHHHH',2,0x3e,1,0,phoff,shoff,0,ehsize,56,phnum,64,shnum,0)
    data[:64]=ehdr
    if phdr_data:
        for i,p in enumerate(phdr_data): data[phoff+i*56:phoff+(i+1)*56]=p
    if shdr_data:
        for i,s in enumerate(shdr_data): data[shoff+i*64:shoff+(i+1)*64]=s
    return bytes(data)

def run(data, name="caseY"):
    open(f"/tmp/probe/{name}",'wb').write(data)
    r=subprocess.run(["/workspace/executable",name], capture_output=True, text=True, cwd="/tmp/probe")
    print(r.returncode, r.stderr.strip().splitlines()[:4])
    if r.returncode==0: return open(f"/tmp/probe/{name}.html").read()
    return None

def phdr(typ=1, flags=5, off=100, filesz=50):
    return struct.pack('<IIQQQQQQ',typ,flags,off,0,0,filesz,filesz,0)
def shdr(name=0,typ=1,off=100,size=50,link=0):
    return struct.pack('<IIQQQQIIQQ',name,typ,0,0,off,size,link,0,1,0)
